func TestGeneratedHeaderDeclarations(t *testing.T) {
	for _, header := range []string{
		"// Code generated by tool. DO NOT EDIT.",
		"\ufeff#!/bin/sh\n# Generated by tool",
		"/* license */\n\n/**\n * @generated\n */",
		"<!-- <auto-generated> -->",
		"(* Automatically generated *)",
		"-- This file is generated by tool",
		"; AUTO-GENERATED file",
		"% Autogenerated file",
	} {
		t.Run(header, func(t *testing.T) {
			path := nativeFixture(t, "source", header+"\nbody\n")
			out := nativeExecute(t, "mcat", path)
			if out.ExitCode != 0 || out.Stdout != header+"\nbody\n" || out.Stderr != "mcat: "+quoteBundlePath(path)+": "+generatedReminder+"\n" {
				t.Fatalf("generated header: %+v", out)
			}
		})
	}
	for _, source := range []string{
		"Generated by tool\n", "value = \"@generated\"\n",
		"// Discussion of generated files\nbody\n", "// This generator is useful\n",
		"// Generated file names are sorted below.\npackage sample\n",
		"// Automatically generated identifiers are useful for testing.\npackage sample\n",
		"code\n// @generated\n", "/* license */ code\n// @generated\n",
	} {
		out := nativeExecute(t, "mcat", nativeFixture(t, "ordinary", source))
		if out.ExitCode != 0 || out.Stdout != source || out.Stderr != "" {
			t.Fatalf("ordinary source %q: %+v", source, out)
		}
	}
}

func TestGeneratedAdvisoryDoesNotDisplaceBundleRows(t *testing.T) {
	component := strings.Repeat("a0b1c2d3e4", 20)
	directory := filepath.Join(t.TempDir(), component, component, component)
	if err := os.MkdirAll(directory, 0700); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(directory, "source")
	if err := os.WriteFile(path, []byte("// ordinary header\n"+strings.Repeat("selected source text row\n", 200)), 0600); err != nil {
		t.Fatal(err)
	}
	const budget = 4000
	args := []string{path, "2:201", path, "2:201", "--max-tokens", "4000"}
	before := nativeExecute(t, "mcat", args...)
	if err := os.WriteFile(path, []byte("// @generated\n"+strings.Repeat("selected source text row\n", 200)), 0600); err != nil {
		t.Fatal(err)
	}
	after := nativeExecute(t, "mcat", args...)
	if before.Stdout != after.Stdout || before.ExitCode != after.ExitCode || after.Stderr == "" {
		t.Fatalf("advisory changed admission: before=%+v after=%+v", before, after)
	}
	if !strings.Contains(after.Stdout, "selected source text row\n") || nativeTokens(t, after.Stdout) > budget || nativeTokens(t, after.Stdout+after.Stderr) <= budget {
		t.Fatalf("fixture must pressure advisory accounting: stdout=%d combined=%d selected=%t", nativeTokens(t, after.Stdout), nativeTokens(t, after.Stdout+after.Stderr), strings.Contains(after.Stdout, "selected source text row\n"))
	}
	for _, out := range []command.Output{before, after} {
		if out.Delivery == nil {
			t.Fatal("expected retained output")
		}
	}
	a, err := before.Delivery.Prepare([]string{"first", "second"})
	if err != nil {
		t.Fatal(err)
	}
	b, err := after.Delivery.Prepare([]string{"first", "second"})
	if err != nil {
		t.Fatal(err)
	}
	if a.Referenced.Stdout != b.Referenced.Stdout || !reflect.DeepEqual(a.Recovery, b.Recovery) || b.Referenced.Stderr == "" {
		t.Fatalf("advisory changed recovery: before=%+v after=%+v", a, b)
	}
}

func TestGeneratedHeaderSelectionsAndBundle(t *testing.T) {
	path := nativeFixture(t, "generated", "// @generated\nsecond\nthird\n")
	for _, args := range [][]string{
		{path, "2:2", "--number"}, {path, "-n", "1"}, {path, "--tail", "-n", "1"},
		{path, "2:2", path, "3:3"},
	} {
		out := nativeExecute(t, "mcat", args...)
		if strings.Count(out.Stderr, generatedReminder) != 1 || strings.Count(out.Stderr, quoteBundlePath(path)) != 1 || strings.Contains(out.Stdout, generatedReminder) {
			t.Fatalf("selection %q: %+v", args, out)
		}
		if args[1] == "2:2" && !strings.Contains(out.Stdout, "second\n") {
			t.Fatalf("missing selected row: %+v", out)
		}
	}
	ordinary := nativeFixture(t, "ordinary", "ordinary\n")
	out := nativeExecute(t, "mcat", path, "2:3", ordinary)
	if out.ExitCode != 0 || strings.Count(out.Stderr, generatedReminder) != 1 || !strings.Contains(out.Stderr, quoteBundlePath(path)) {
		t.Fatalf("mixed bundle: %+v", out)
	}
}

func TestGeneratedBundleAdvisoryListsUniquePathsInSourceOrder(t *testing.T) {
	first := nativeFixture(t, "first", "// @generated\nfirst row\n")
	second := nativeFixture(t, "second", "// @generated\nsecond row\n")
	ordinary := nativeFixture(t, "ordinary", "ordinary row\n")
	missing := filepath.Join(t.TempDir(), "missing")
	out := nativeExecute(t, "mcat", second, "1:1", "2:2", ordinary, first, "2:2", second, "2:2", missing)
	if out.ExitCode != 1 || strings.Count(out.Stderr, generatedReminder) != 1 || strings.Count(out.Stderr, quoteBundlePath(first)) != 1 || strings.Count(out.Stderr, quoteBundlePath(second)) != 1 {
		t.Fatalf("generated bundle advisory: %+v", out)
	}
	if strings.Index(out.Stderr, quoteBundlePath(second)) > strings.Index(out.Stderr, quoteBundlePath(first)) || strings.Contains(out.Stderr, quoteBundlePath(ordinary)) || !strings.Contains(out.Stderr, "ENOENT") {
		t.Fatalf("source order or diagnostics changed: %+v", out)
	}
	if strings.Count(out.Stdout, "second row\n") != 2 || strings.Count(out.Stdout, "first row\n") != 1 || !strings.Contains(out.Stdout, "ordinary row\n") {
		t.Fatalf("selection bodies changed: %+v", out)
	}
}

func TestGeneratedReminderSurvivesBudgetRedistribution(t *testing.T) {
	path := nativeFixture(t, "generated", "// @generated\n"+strings.Repeat("body content\n", 2000))
	ordinary := nativeFixture(t, "empty", "")
	for _, args := range [][]string{{path, "--max-tokens", "300"}, {path, ordinary, "--max-tokens", "300"}} {
		out := nativeExecute(t, "mcat", args...)
		if out.ExitCode != 1 || !strings.Contains(out.Stderr, generatedReminder) || nativeTokens(t, out.Stdout) > 300 {
			t.Fatalf("bounded output: %+v", out)
		}
		if out.OmittedOutput == nil && out.Delivery == nil {
			t.Fatal("generated reminder lost recovery")
		}
	}
}
